import { existsSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

// The guide pages are generated by scripts/build-guides.ts before Vite runs.
const guidesDir = resolve(import.meta.dirname, 'guides');
const guides = existsSync(guidesDir)
  ? readdirSync(guidesDir).filter((file) => file.endsWith('.html'))
  : [];

export default defineConfig({
  build: {
    rollupOptions: {
      input: {
        main: resolve(import.meta.dirname, 'index.html'),
        ...Object.fromEntries(
          guides.map((file) => [
            `guides/${file.slice(0, -'.html'.length)}`,
            resolve(guidesDir, file),
          ]),
        ),
      },
    },
  },
});
